using System;using System.IO;using System.Linq;using System.Threading.Tasks;using UnityEngine;using UnityEditor;using AntColony.Units;using AntColony.Core;
public static class EquipmentFlipBow1112{
 public static async Task<string> Run(){var c=CommanderRoster.Instance.Commanders.First(x=>x&&x.IsColonyMember);var v=c.GetComponent<AntVisual>();var p=c.GetComponent<MeshyNativeMotionPlayer>();var cc=UnityEngine.Object.FindAnyObjectByType<AntColony.Camera.IsometricCameraController>();if(cc)cc.enabled=false;var cam=Camera.main;var model=c.transform.Find("Kemono");var old=c.PersonalState.equipment.ToArray();AntColony.UI.SimulationPause.UserSpeed(0);EditorApplication.isPaused=false;var report=new System.Collections.Generic.List<string>();
 var rt=new RenderTexture(640,640,24);var tex=new Texture2D(640,640,TextureFormat.RGB24,false);var prior=cam.targetTexture;var active=RenderTexture.active;
 try{foreach(var kind in new[]{WeaponKind.ShortBow,WeaponKind.GrandBow,WeaponKind.Shield}){
 c.CommandStop();c.PersonalState.equipment.RemoveAll(e=>e.slot==EquipmentSlot.Weapon);c.PersonalState.equipment.Add(new EquipmentItem{slot=EquipmentSlot.Weapon,weapon=kind});c.RefreshEquipment();v.Attack(c.Position+Vector3.forward*4);var lib=Resources.Load<MeshyNativeLibrary>("MeshyNative/Runtime");p.PreviewMotion=lib.actions.First(a=>a.action==v.MotionName).motion;p.PreviewPhase=-1;await Task.Delay(200);
 var focus=c.Position+model.localPosition+Vector3.up*.8f;cam.transform.position=focus+model.right*2.4f+model.forward*2+Vector3.up*.15f;cam.transform.LookAt(focus);cam.orthographicSize=1.15f;cam.nearClipPlane=.02f;string path="work/equipment-flip-1112/"+kind;Directory.CreateDirectory(path);
 float support=0,delta=0;var bones=p.NativeModel.GetComponentsInChildren<Transform>().ToDictionary(t=>t.name);var names=new[]{"RightForeArm","RightHand","LeftForeArm","LeftHand"};var lengths=names.Select(n=>Vector3.Distance(bones["mixamorig:"+n].position,bones["mixamorig:"+n].parent.position)).ToArray();
 for(int i=0;i<30;i++){await Task.Delay(80);var grip=p.NativeModel.GetComponentInParent<MeshyNativeEquipment>();support=Mathf.Max(support,grip.SupportShaftError);for(int j=0;j<names.Length;j++)delta=Mathf.Max(delta,Mathf.Abs(lengths[j]-Vector3.Distance(bones["mixamorig:"+names[j]].position,bones["mixamorig:"+names[j]].parent.position)));cam.targetTexture=rt;cam.Render();RenderTexture.active=rt;tex.ReadPixels(new Rect(0,0,640,640),0,0);tex.Apply();File.WriteAllBytes(path+"/"+i.ToString("D3")+".png",tex.EncodeToPNG());}
 report.Add(kind+" / "+p.PlayingMotion+" support="+support+" boneLengthChange="+delta);if(delta>.0001f)throw new Exception("Bone stretch "+kind);if(MeshyEquipmentRules.IsFirearm(kind)&&support>.015f)throw new Exception("Support misses gun "+kind+" "+support);
 }File.WriteAllLines("work/equipment-flip-1112/bow-playback.txt",report);return string.Join("\n",report);
 }finally{cam.targetTexture=prior;RenderTexture.active=active;UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(tex);c.PersonalState.equipment.Clear();c.PersonalState.equipment.AddRange(old);c.RefreshEquipment();p.PreviewMotion=null;p.PreviewPhase=-1;v.Action("Idle_A");}}
}
